class Algorithms {
    static int linearSearch(int[] values, int target) {
        for (int i = 0; i < values.length; i++) {
            if (values[i] == target) {
                return i;
            }
        }
        return -1;
    }
}

class Algorithms {
    static int binarySearch(int[] values, int target) {
        int low = 0;
        int high = values.length - 1;
        while (low <= high) {
            int mid = low + (high - low) / 2;
            if (values[mid] == target) {
                return mid;
            } else if (values[mid] < target) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }
        return -1;
    }
}

class Algorithms {
    static void bubbleSort(int[] values) {
        for (int i = 0; i < values.length - 1; i++) {
            boolean swapped = false;
            for (int j = 0; j < values.length - 1 - i; j++) {
                if (values[j] > values[j + 1]) {
                    int temp = values[j];
                    values[j] = values[j + 1];
                    values[j + 1] = temp;
                    swapped = true;
                }
            }
            if (!swapped) {
                return;
            }
        }
    }
}

class Algorithms {
    static void selectionSort(int[] values) {
        for (int i = 0; i < values.length - 1; i++) {
            int minIndex = i;
            for (int j = i + 1; j < values.length; j++) {
                if (values[j] < values[minIndex]) {
                    minIndex = j;
                }
            }
            int temp = values[i];
            values[i] = values[minIndex];
            values[minIndex] = temp;
        }
    }
}

class Algorithms {
    static void insertionSort(int[] values) {
        for (int i = 1; i < values.length; i++) {
            int current = values[i];
            int j = i - 1;
            while (j >= 0 && values[j] > current) {
                values[j + 1] = values[j];
                j--;
            }
            values[j + 1] = current;
        }
    }
}

import java.util.Arrays;

class Algorithms {
    static int[] mergeSort(int[] values) {
        if (values.length <= 1) {
            return values.clone();
        }
        int mid = values.length / 2;
        int[] left = mergeSort(Arrays.copyOfRange(values, 0, mid));
        int[] right = mergeSort(Arrays.copyOfRange(values, mid, values.length));
        return merge(left, right);
    }

    private static int[] merge(int[] left, int[] right) {
        int[] result = new int[left.length + right.length];
        int i = 0;
        int j = 0;
        while (i < left.length || j < right.length) {
            if (j >= right.length || (i < left.length && left[i] <= right[j])) {
                result[i + j] = left[i];
                i++;
            } else {
                result[i + j] = right[j];
                j++;
            }
        }
        return result;
    }
}

class Algorithms {
    static void quickSort(int[] values) {
        quickSort(values, 0, values.length - 1);
    }

    private static void quickSort(int[] values, int low, int high) {
        if (low >= high) {
            return;
        }
        int pivotIndex = partition(values, low, high);
        quickSort(values, low, pivotIndex - 1);
        quickSort(values, pivotIndex + 1, high);
    }

    private static int partition(int[] values, int low, int high) {
        int pivot = values[high];
        int i = low - 1;
        for (int j = low; j < high; j++) {
            if (values[j] <= pivot) {
                i++;
                int temp = values[i];
                values[i] = values[j];
                values[j] = temp;
            }
        }
        int temp = values[i + 1];
        values[i + 1] = values[high];
        values[high] = temp;
        return i + 1;
    }
}

class Algorithms {
    static void heapSort(int[] values) {
        int n = values.length;
        for (int i = n / 2 - 1; i >= 0; i--) {
            siftDown(values, i, n);
        }
        for (int end = n - 1; end > 0; end--) {
            int temp = values[0];
            values[0] = values[end];
            values[end] = temp;
            siftDown(values, 0, end);
        }
    }

    private static void siftDown(int[] values, int start, int end) {
        int root = start;
        while (root * 2 + 1 < end) {
            int child = root * 2 + 1;
            if (child + 1 < end && values[child + 1] > values[child]) {
                child++;
            }
            if (values[root] >= values[child]) {
                return;
            }
            int temp = values[root];
            values[root] = values[child];
            values[child] = temp;
            root = child;
        }
    }
}

