class Graph {
    private final Map<String, List<String>> edges = new HashMap<>();

    void addEdge(String from, String to) {
        edges.computeIfAbsent(from, key -> new ArrayList<>()).add(to);
        edges.computeIfAbsent(to, key -> new ArrayList<>()).add(from);
    }

    List<String> neighbors(String node) {
        return edges.getOrDefault(node, List.of());
    }
}

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Queue;
import java.util.Set;

class Algorithms {
    static List<String> bfs(Graph graph, String start) {
        List<String> order = new ArrayList<>();
        Set<String> visited = new HashSet<>();
        Queue<String> queue = new ArrayDeque<>();
        visited.add(start);
        queue.add(start);
        while (!queue.isEmpty()) {
            String node = queue.remove();
            order.add(node);
            for (String neighbor : graph.neighbors(node)) {
                if (visited.add(neighbor)) {
                    queue.add(neighbor);
                }
            }
        }
        return order;
    }
}

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

class Algorithms {
    static List<String> dfs(Graph graph, String start) {
        List<String> order = new ArrayList<>();
        visit(graph, start, new HashSet<>(), order);
        return order;
    }

    private static void visit(
            Graph graph, String node, Set<String> visited, List<String> order) {
        if (!visited.add(node)) {
            return;
        }
        order.add(node);
        for (String neighbor : graph.neighbors(node)) {
            visit(graph, neighbor, visited, order);
        }
    }
}

import java.util.ArrayList;
