import java.util.List;
import java.util.Map;
import java.util.Set;

class WeightedGraph {
    record Edge(String to, int weight) {}

    private final Map<String, List<Edge>> edges = new HashMap<>();

    void addEdge(String from, String to, int weight) {
        edges.computeIfAbsent(from, key -> new ArrayList<>()).add(new Edge(to, weight));
        edges.computeIfAbsent(to, key -> new ArrayList<>()).add(new Edge(from, weight));
    }

    List<Edge> neighbors(String node) {
        return edges.getOrDefault(node, List.of());
    }
}

class Algorithms {
    static Map<String, Long> dijkstra(WeightedGraph graph, String start) {
        Map<String, Long> distances = new HashMap<>();
        distances.put(start, 0L);
        Set<String> visited = new HashSet<>();
        while (true) {
            String node = null;
            long best = Long.MAX_VALUE;
            for (var entry : distances.entrySet()) {
                if (!visited.contains(entry.getKey()) && entry.getValue() < best) {
                    best = entry.getValue();
                    node = entry.getKey();
                }
            }
            if (node == null) {
                break;
            }
            visited.add(node);
            for (WeightedGraph.Edge edge : graph.neighbors(node)) {
                long candidate = best + edge.weight();
                if (candidate < distances.getOrDefault(edge.to(), Long.MAX_VALUE)) {
                    distances.put(edge.to(), candidate);
                }
            }
        }
        return distances;
    }
}
